import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def get_pkg_map(data):
    result = {}
    for proj in data['projects']:
        pname = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            for pkg in fw.get('topLevelPackages', []):
                key = (pname, fw['framework'], pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

b = get_pkg_map(baseline)
a = get_pkg_map(after)

changes = []
unchanged = []
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    proj, fw, pkg = key
    bv = b.get(key, 'N/A')
    av = a.get(key, 'N/A')
    if bv != av:
        changes.append((proj, fw, pkg, bv, av))
    else:
        unchanged.append((proj, fw, pkg, bv))

print('=== CHANGES ===')
if changes:
    for proj, fw, pkg, bv, av in changes:
        print(f'  {proj} ({fw}): {pkg} {bv} -> {av}')
else:
    print('  None')

print(f'\n=== UNCHANGED: {len(unchanged)} packages ===')
for proj, fw, pkg, v in unchanged:
    print(f'  {proj} ({fw}): {pkg} {v}')
"

